import SwiftUI
import Photos
import UserNotifications
import UIKit

struct LiberonsNotificationSettingsView: View {
    @ObservedObject var language: LanguageStore
    @AppStorage("notify.backupComplete") private var backupComplete = true
    @AppStorage("notify.readyToFree") private var readyToFree = true
    @AppStorage("notify.backupInterrupted") private var backupInterrupted = true
    @AppStorage("notify.storageWarnings") private var storageWarnings = true
    @AppStorage("notify.backupReminder") private var backupReminder = false
    @State private var authorization: UNAuthorizationStatus = .notDetermined

    var body: some View {
        List {
            Section {
                statusRow
                if authorization == .notDetermined { Button(language.text("Allow notifications", "Autoriser les notifications")) { requestPermission() } }
                else if authorization == .denied { Button(language.text("Open iPhone Settings", "Ouvrir les réglages de l’iPhone")) { openSettings() } }
            } footer: { Text(language.text("Choose the alerts you want to receive from Libérons. You can change them at any time.", "Choisissez les alertes que vous souhaitez recevoir de Libérons. Vous pourrez les modifier à tout moment.")) }
            Section(language.text("Your backups", "Vos sauvegardes")) {
                notificationToggle(language.text("Backup finished", "Sauvegarde terminée"), subtitle: language.text("Know when your selected memories are safely saved.", "Soyez averti lorsque les souvenirs sélectionnés sont bien sauvegardés."), icon: "checkmark.circle.fill", isOn: $backupComplete)
                notificationToggle(language.text("Space can be freed", "Vous pouvez libérer de l’espace"), subtitle: language.text("Get an alert when saved memories can be removed from your iPhone to recover space.", "Recevez une alerte lorsque des souvenirs sauvegardés peuvent être retirés de l’iPhone pour récupérer de l’espace."), icon: "iphone.and.arrow.forward", isOn: $readyToFree)
                notificationToggle(language.text("Backup problem", "Problème de sauvegarde"), subtitle: language.text("Be notified if a backup stops or needs your attention.", "Soyez averti si une sauvegarde s’arrête ou nécessite votre attention."), icon: "exclamationmark.triangle.fill", isOn: $backupInterrupted)
            }
            Section(language.text("Space & reminders", "Espace et rappels")) {
                notificationToggle(language.text("Storage almost full", "Espace Libérons presque plein"), subtitle: language.text("Get a warning before your Libérons storage reaches its limit.", "Recevez une alerte avant que votre espace Libérons n’atteigne sa limite."), icon: "externaldrive.badge.exclamationmark", isOn: $storageWarnings)
                notificationToggle(language.text("Remind me to back up", "Me rappeler de sauvegarder"), subtitle: language.text("Receive an occasional reminder when new memories have not been backed up for a while.", "Recevez un rappel occasionnel lorsque de nouveaux souvenirs n’ont pas été sauvegardés depuis un moment."), icon: "clock.badge", isOn: $backupReminder)
            }
            if authorization == .authorized || authorization == .provisional || authorization == .ephemeral {
                Section { Button(language.text("Notification settings on iPhone", "Réglages des notifications sur l’iPhone")) { openSettings() } } footer: { Text(language.text("Sound, banners and Lock Screen alerts are managed by iPhone Settings.", "Le son, les bannières et l’affichage sur l’écran verrouillé sont gérés dans les réglages de l’iPhone.")) }
            }
        }.navigationTitle(language.text("Notifications", "Notifications")).navigationBarTitleDisplayMode(.inline).task { await refreshAuthorization() }
    }
    private var statusRow: some View { HStack(spacing: 12) { Image(systemName: authorization == .denied ? "bell.slash.fill" : "bell.badge.fill").foregroundStyle(authorization == .denied ? Color.red : Color.blue).frame(width: 24); VStack(alignment: .leading, spacing: 2) { Text(language.text("Notifications on this iPhone", "Notifications sur cet iPhone")); Text(statusText).font(.caption).foregroundStyle(.secondary) }; Spacer() } }
    private func notificationToggle(_ title: String, subtitle: String, icon: String, isOn: Binding<Bool>) -> some View { Toggle(isOn: isOn) { HStack(alignment: .top, spacing: 12) { Image(systemName: icon).frame(width: 24).padding(.top, 2); VStack(alignment: .leading, spacing: 3) { Text(title); Text(subtitle).font(.caption).foregroundStyle(.secondary) } } }.disabled(authorization == .denied) }
    private var statusText: String { switch authorization { case .authorized, .provisional, .ephemeral: return language.text("On", "Activées"); case .denied: return language.text("Off in iPhone Settings", "Désactivées dans les réglages de l’iPhone"); case .notDetermined: return language.text("Not set up yet", "Pas encore configurées"); @unknown default: return "—" } }
    private func refreshAuthorization() async { authorization = await UNUserNotificationCenter.current().notificationSettings().authorizationStatus }
    private func requestPermission() { Task { _ = try? await UNUserNotificationCenter.current().requestAuthorization(options: [.alert, .sound, .badge]); await refreshAuthorization() } }
    private func openSettings() { guard let url = URL(string: UIApplication.openNotificationSettingsURLString) else { return }; UIApplication.shared.open(url) }
}

struct LiberonsPrivacySecurityView: View {
    @ObservedObject var language: LanguageStore
    @State private var photoStatus = PHPhotoLibrary.authorizationStatus(for: .readWrite)
    var body: some View {
        List {
            Section { HStack(spacing: 12) { Image(systemName: "photo.stack.fill").foregroundStyle(.blue).frame(width: 24); VStack(alignment: .leading, spacing: 2) { Text(language.text("Photos access", "Accès aux photos")); Text(photoAccessText).font(.caption).foregroundStyle(.secondary) }; Spacer(); Image(systemName: photoStatus == .authorized ? "checkmark.circle.fill" : "chevron.right").foregroundStyle(photoStatus == .authorized ? Color.green : Color.secondary.opacity(0.45)) }.contentShape(Rectangle()).onTapGesture { openAppSettings() } } footer: { Text(language.text("Libérons uses Photos access only for the backup, protection and recovery features you choose.", "Libérons utilise l’accès à Photos uniquement pour les fonctions de sauvegarde, de protection et de récupération que vous choisissez.")) }
            Section(language.text("Protection principles", "Principes de protection")) {
                Label(language.text("An item is marked protected only after its cloud copy is confirmed.", "Un élément est marqué comme protégé uniquement après confirmation de sa copie dans le cloud."), systemImage: "checkmark.shield.fill")
                Label(language.text("Nothing is removed from your iPhone automatically. You remain in control.", "Rien n’est retiré automatiquement de votre iPhone. Vous gardez le contrôle."), systemImage: "hand.raised.fill")
                Label(language.text("Libérons does not sell your protected content or use it for targeted advertising.", "Libérons ne vend pas vos contenus protégés et ne les utilise pas pour de la publicité ciblée."), systemImage: "eye.slash.fill")
            }
            Section {
                external(.privacy, icon: "hand.raised.square.fill", language.text("Privacy Policy", "Politique de confidentialité"))
                external(.terms, icon: "doc.text.fill", language.text("Terms of Use", "Conditions d’utilisation"))
                external(.refunds, icon: "arrow.uturn.backward.circle.fill", language.text("Refund Policy", "Politique de remboursement"))
            } header: { Text(language.text("Legal & privacy", "Cadre juridique et confidentialité")) }
            footer: { Text(language.text("Review the terms and privacy commitments that apply to your Libérons account.", "Consultez les conditions et engagements de confidentialité applicables à votre compte Libérons.")) }
            Section(language.text("This iPhone", "Cet iPhone")) { Button(language.text("Open Libérons settings", "Ouvrir les réglages de Libérons")) { openAppSettings() } }
        }.navigationTitle(language.text("Privacy & security", "Confidentialité et sécurité")).navigationBarTitleDisplayMode(.inline).onAppear { photoStatus = PHPhotoLibrary.authorizationStatus(for: .readWrite) }
    }
    @ViewBuilder private func external(_ destination: LiberonsWebDestination, icon: String, _ title: String) -> some View { LiberonsExternalRow(icon: icon, title: title, subtitle: language.text("View document", "Consulter le document")) { open(destination) } }
    private var photoAccessText: String { switch photoStatus { case .authorized: return language.text("All photos allowed", "Toutes les photos autorisées"); case .limited: return language.text("Selected photos only", "Certaines photos seulement"); case .denied, .restricted: return language.text("Access is off", "Accès désactivé"); case .notDetermined: return language.text("Not set up yet", "Pas encore configuré"); @unknown default: return "—" } }
    private func open(_ destination: LiberonsWebDestination) { guard let url = destination.url(for: language.language) else { return }; UIApplication.shared.open(url) }
    private func openAppSettings() { guard let url = URL(string: UIApplication.openSettingsURLString) else { return }; UIApplication.shared.open(url) }
}

struct LiberonsHelpSupportView: View {
    @ObservedObject var language: LanguageStore
    @State private var searchText = ""
    @State private var selectedCategory = "all"

    private struct FAQItem: Identifiable { let id:String; let category:String; let questionEN:String; let questionFR:String; let answerEN:String; let answerFR:String; let keywords:String }
    private var categories:[(String,String,String)] { [("all","All","Tout"),("backup","Protection","Protection"),("files","Files","Fichiers"),("space","Space","Espace"),("restore","Restore","Récupération"),("account","Account","Compte"),("billing","Billing","Facturation"),("security","Security","Sécurité"),("troubleshooting","Problems","Problèmes")] }

    private var items:[FAQItem] { [
        item("protected","backup","When is an item considered protected?","Quand un élément est-il considéré comme protégé ?","Only after the original has been transferred and Libérons has confirmed the protected cloud copy. Starting a transfer is never enough to mark an item as protected.","Uniquement après le transfert de l’original et la confirmation de sa copie protégée par Libérons. Le simple démarrage d’un transfert ne suffit jamais pour déclarer un élément protégé.","protégé protection confirmation original transfert sauvegarde"),
        item("background","backup","Can protection continue when I leave the app?","La protection peut-elle continuer quand je quitte l’app ?","Libérons uses the background capabilities made available by iOS. The system may still pause work because of battery, network, thermal conditions or if the app is force-quit. Reopening Libérons allows pending work to continue when necessary.","Libérons utilise les capacités d’arrière-plan mises à disposition par iOS. Le système peut néanmoins suspendre le travail selon la batterie, le réseau, la température de l’appareil ou si l’app est forcée à quitter. Rouvrir Libérons permet au travail en attente de reprendre lorsque nécessaire.","arrière plan fermer quitter pause batterie réseau"),
        item("wifi","backup","Do I need Wi-Fi to protect my content?","Ai-je besoin du Wi-Fi pour protéger mes contenus ?","Not necessarily. A stable connection is recommended for large libraries and large videos. Network conditions can affect transfer speed and continuity.","Pas nécessairement. Une connexion stable est recommandée pour les grandes bibliothèques et les vidéos volumineuses. Les conditions réseau peuvent influencer la vitesse et la continuité des transferts.","wifi données mobiles réseau internet"),
        item("icloud","backup","What if an original is only in iCloud Photos?","Et si l’original est seulement dans Photos iCloud ?","Libérons can request the original through Photos when iOS makes it available. Protection can take longer because the iPhone may first need to retrieve the original from iCloud.","Libérons peut demander l’original via Photos lorsqu’iOS le rend disponible. La protection peut prendre plus de temps car l’iPhone peut devoir récupérer l’original depuis iCloud avant son transfert.","icloud photos original récupérer"),
        item("pause","backup","Can I pause or stop protection?","Puis-je mettre la protection en pause ou l’arrêter ?","Yes. You can pause or stop active work. Items whose protection was already confirmed remain protected.","Oui. Vous pouvez mettre en pause ou arrêter le travail actif. Les éléments dont la protection a déjà été confirmée restent protégés.","pause arrêter reprendre file"),
        item("duplicates","backup","Will Libérons protect the same item twice?","Libérons va-t-il protéger le même élément deux fois ?","Libérons is designed to recognize content already protected and avoid unnecessary duplicate protection work.","Libérons est conçu pour reconnaître les contenus déjà protégés et éviter les protections en double inutiles.","doublon double déjà protégé"),

        item("files-supported","files","What types of files can I protect?","Quels types de fichiers puis-je protéger ?","Libérons can protect files accessible through the iOS Files picker, including documents, PDFs, images, videos, audio files and archives, as well as other compatible file formats made available by your file provider.","Libérons peut protéger les fichiers accessibles depuis le sélecteur Fichiers d’iOS, notamment les documents, PDF, images, vidéos, fichiers audio et archives, ainsi que les autres formats compatibles rendus disponibles par votre fournisseur de fichiers.","fichier pdf zip archive wav mp3 m4a document audio vidéo image"),
        item("files-analyze","files","How does File Analysis work?","Comment fonctionne l’Analyse des fichiers ?","Open File Analysis, choose a location in Files, navigate to the folder you want to inspect and tap Open. Libérons analyzes the accessible files in that folder and shows their type and size so you can choose what to protect or delete.","Ouvrez Analyse des fichiers, choisissez un emplacement dans Fichiers, accédez au dossier à examiner puis touchez « Ouvrir ». Libérons analyse les fichiers accessibles de ce dossier et affiche leur type et leur taille afin que vous puissiez choisir ceux à protéger ou à supprimer.","analyse fichiers dossier ouvrir taille type sélectionner"),
        item("files-destination","files","Where do photos and videos selected from Files appear?","Où apparaissent les photos et vidéos sélectionnées depuis Fichiers ?","Content is organized by its actual type after protection. A protected image appears in Library under Photos, a protected video under Videos, and other protected files in Protected Files.","Après protection, le contenu est classé selon son type réel. Une image protégée apparaît dans Bibliothèque, section Photos ; une vidéo protégée dans la section Vidéos ; les autres fichiers apparaissent dans Fichiers protégés.","fichiers destination photo vidéo bibliothèque fichiers protégés"),
        item("files-originals","files","Can I remove a file after protecting it?","Puis-je supprimer un fichier après l’avoir protégé ?","Yes. When Libérons offers removal after protection, deletion is performed only after the protected copy has been confirmed. Some file locations or providers may refuse deletion; in that case the protected Libérons copy remains available.","Oui. Lorsque Libérons propose la suppression après protection, l’original n’est supprimé qu’après confirmation de la copie protégée. Certains emplacements ou fournisseurs de fichiers peuvent refuser la suppression ; dans ce cas, la copie protégée dans Libérons reste disponible.","fichier supprimer original après protection fournisseur"),
        item("files-delete-unprotected","files","What does Delete without protecting mean?","Que signifie Supprimer sans protéger ?","This action deletes the selected files from their current location without first creating a protected Libérons copy. Use it only for content you no longer need. Depending on the file provider, deletion can be permanent.","Cette action supprime les fichiers sélectionnés de leur emplacement actuel sans créer au préalable de copie protégée dans Libérons. Utilisez-la uniquement pour des contenus dont vous n’avez plus besoin. Selon le fournisseur de fichiers, la suppression peut être définitive.","supprimer sans protéger fichier définitif"),
        item("files-restore","restore","Can I save a protected file back to Files?","Puis-je réenregistrer un fichier protégé dans Fichiers ?","Yes. From Protected Files, choose Save to Files, select the destination and confirm. Libérons reports success only after iOS confirms the save operation.","Oui. Depuis Fichiers protégés, choisissez « Enregistrer dans Fichiers », sélectionnez la destination puis confirmez. Libérons n’affiche la réussite qu’après confirmation de l’enregistrement par iOS.","restaurer fichier enregistrer dans fichiers exporter"),

        item("free-space","space","What happens when I free space?","Que se passe-t-il quand je libère de l’espace ?","Only originals already confirmed as protected are eligible. After you approve the Photos deletion, the local copy is removed while the protected Libérons copy remains in your Library.","Seuls les originaux dont la protection a été confirmée sont éligibles. Après votre confirmation de suppression dans Photos, la copie locale est retirée tandis que la copie protégée reste dans votre Bibliothèque Libérons.","libérer espace supprimer iphone local"),
        item("automatic-delete","space","Does Libérons delete photos automatically?","Libérons supprime-t-il mes photos automatiquement ?","No. Protection and local deletion are separate actions. Libérons requires your action before asking Photos to remove protected originals from the device.","Non. La protection et la suppression locale sont deux actions distinctes. Libérons nécessite votre action avant de demander à Photos de retirer des originaux protégés de l’appareil.","automatique suppression contrôle permission"),
        item("large-recently-deleted","space","I protected more than 4,000 photos. How should I empty Recently Deleted?","J’ai protégé plus de 4 000 photos. Comment vider Supprimés récemment ?","For a very large Recently Deleted collection, avoid trying to permanently delete the entire collection in one operation. On some iPhones, very large deletion requests can become slow, appear unresponsive or fail to complete cleanly. For a smoother operation, delete progressively: start with batches of about 500 items, repeat until the collection becomes lighter, then you can increase to batches of about 1,000 if the iPhone remains responsive. Wait for each batch to finish before starting the next one. Before permanently deleting anything, verify in Libérons that the content you want to keep is protected. Permanent deletion from Recently Deleted cannot be undone.","Pour une collection Supprimés récemment très volumineuse, évitez de lancer la suppression définitive de l’ensemble en une seule opération. Sur certains iPhone, une demande portant sur plusieurs milliers d’éléments peut devenir très lente, sembler bloquée ou ne pas se terminer correctement. Pour une suppression plus stable, procédez progressivement : commencez par des lots d’environ 500 éléments, répétez l’opération jusqu’à alléger la collection, puis vous pouvez passer à des lots d’environ 1 000 éléments si l’iPhone reste réactif. Attendez la fin de chaque lot avant de lancer le suivant. Avant toute suppression définitive, vérifiez dans Libérons que les contenus que vous souhaitez conserver sont bien protégés. Une suppression depuis Supprimés récemment est irréversible.","4000 4 000 supprimés récemment 500 1000 mille supprimer tout lot photos iphone"),
        item("recently-deleted","space","Why is space not fully recovered after deletion?","Pourquoi l’espace n’est-il pas entièrement récupéré après la suppression ?","Photos normally moves deleted media to Recently Deleted for up to 30 days. To recover the local space sooner, you can permanently remove those items from Recently Deleted. Libérons cannot perform that final Photos action for you.","Photos place normalement les médias supprimés dans Supprimés récemment pendant une période pouvant aller jusqu’à 30 jours. Pour récupérer plus rapidement l’espace local, vous pouvez supprimer définitivement ces éléments depuis Supprimés récemment. Libérons ne peut pas effectuer cette dernière action Photos à votre place.","supprimés récemment espace 30 jours photos vider"),
        item("icloud-delete","space","What happens if I use iCloud Photos and delete an original?","Que se passe-t-il si j’utilise Photos iCloud et que je supprime un original ?","When iCloud Photos is enabled, deleting a photo or video in Photos can also remove it from other devices signed in to the same Apple Account. Confirm that the Libérons copy is protected before deleting an original you want to keep.","Lorsque Photos iCloud est activé, supprimer une photo ou une vidéo dans Photos peut également la supprimer des autres appareils connectés au même compte Apple. Vérifiez que la copie Libérons est protégée avant de supprimer un original que vous souhaitez conserver.","icloud suppression autres appareils compte apple"),
        item("backup-only","space","Can I protect content without freeing space?","Puis-je protéger mes contenus sans libérer d’espace ?","Yes. Protection does not require removal of the iPhone copy. You decide if and when you want to reclaim local space.","Oui. La protection ne vous oblige pas à retirer la copie de l’iPhone. Vous décidez si et quand vous souhaitez récupérer de l’espace local.","garder iphone sans supprimer"),
        item("full","space","What happens when my Libérons storage is full?","Que se passe-t-il si mon stockage Libérons est plein ?","Existing protected content remains in your Library. New protection transfers pause until capacity becomes available or your plan provides more storage.","Les contenus déjà protégés restent dans votre Bibliothèque. Les nouveaux transferts de protection sont suspendus jusqu’à ce que de l’espace soit disponible ou que votre forfait fournisse davantage de stockage.","plein capacité forfait stockage"),

        item("restore","restore","Can I restore a protected photo or video to Photos?","Puis-je restaurer une photo ou vidéo protégée dans Photos ?","Yes. When original recovery is available for your account, Libérons can retrieve the protected original and save it back to your photo library after the required Photos permission.","Oui. Lorsque la récupération des originaux est disponible pour votre compte, Libérons peut récupérer l’original protégé et le réenregistrer dans votre photothèque après l’autorisation Photos nécessaire.","restaurer récupérer galerie photos original"),
        item("new-phone","restore","What happens if I change or lose my iPhone?","Que se passe-t-il si je change ou perds mon iPhone ?","Sign in to the same Libérons account on the new device. Protected content is associated with your account rather than a single physical iPhone. Security checks and permissions may be required on the new device.","Connectez-vous au même compte Libérons sur le nouvel appareil. Les contenus protégés sont associés à votre compte plutôt qu’à un seul iPhone physique. Des vérifications de sécurité et autorisations peuvent être demandées sur le nouvel appareil.","nouveau téléphone perdu cassé appareil récupération"),
        item("restore-limit","restore","Why can original recovery be temporarily limited?","Pourquoi la récupération d’originaux peut-elle être temporairement limitée ?","Protective safeguards may temporarily slow or limit unusually intensive repeated original transfers. Your protected content remains stored during such a temporary restriction.","Des mesures de protection peuvent temporairement ralentir ou limiter des transferts d’originaux répétés et exceptionnellement intensifs. Vos contenus protégés restent conservés pendant cette restriction temporaire.","limite restauration intensive téléchargement original"),

        item("signin","account","Do I need an account?","Ai-je besoin d’un compte ?","Yes. Your account associates your protected content, storage allowance, devices and subscription state with you.","Oui. Votre compte associe vos contenus protégés, votre espace de stockage, vos appareils et l’état de votre abonnement.","compte connexion inscription"),
        item("signout","account","Does signing out delete my protected content?","Se déconnecter supprime-t-il mes contenus protégés ?","No. Signing out removes the active session from that device; it does not by itself delete protected content from your Libérons account.","Non. La déconnexion retire la session active de cet appareil ; elle ne supprime pas à elle seule les contenus protégés de votre compte Libérons.","déconnexion fichiers supprimer"),
        item("devices","account","Can I use Libérons on another iPhone?","Puis-je utiliser Libérons sur un autre iPhone ?","You can sign in on another supported device. Account and device protections may apply, while paid storage rights remain associated with the account.","Vous pouvez vous connecter sur un autre appareil compatible. Des protections liées au compte et à l’appareil peuvent s’appliquer, tandis que les droits de stockage payants restent associés au compte.","appareil multiple iphone autre téléphone"),

        item("free-tier","billing","How does free storage work?","Comment fonctionne le stockage gratuit ?","Eligible accounts can receive the free storage allowance displayed by Libérons. Eligibility protections may prevent repeated account creation from generating additional free allowances.","Les comptes éligibles peuvent recevoir l’espace gratuit affiché par Libérons. Des protections d’éligibilité peuvent empêcher la création répétée de comptes de générer des espaces gratuits supplémentaires.","gratuit offre plusieurs comptes"),
        item("subscription","billing","Where do I subscribe or manage my plan?","Où puis-je m’abonner ou gérer mon forfait ?","Subscriptions and plan management are handled through the official Libérons account and billing experience. The app reflects the storage allowance associated with your account.","Les abonnements et la gestion des forfaits sont effectués depuis l’expérience officielle de compte et de facturation Libérons. L’app reflète l’espace de stockage associé à votre compte.","abonnement forfait paiement site"),
        item("uninstall","billing","Does deleting the app cancel my subscription?","Supprimer l’app annule-t-il mon abonnement ?","No. Uninstalling Libérons or signing out does not cancel a subscription. Use the official account and billing controls to manage or cancel a paid plan.","Non. Désinstaller Libérons ou vous déconnecter n’annule pas un abonnement. Utilisez les contrôles officiels du compte et de facturation pour gérer ou annuler un forfait payant.","désinstaller annuler abonnement"),
        item("payment-failed","billing","What happens if a subscription payment fails?","Que se passe-t-il si le paiement de mon abonnement échoue ?","New protection transfers can be paused while payment is being regularized. Access to original recovery may also become restricted according to the applicable grace period and account status. A payment failure does not instantly erase protected content.","Les nouveaux transferts de protection peuvent être suspendus pendant la régularisation du paiement. L’accès à la récupération des originaux peut également devenir restreint selon la période de grâce applicable et l’état du compte. Un échec de paiement n’efface pas instantanément les contenus protégés.","paiement échoué grâce récupération facture carte"),

        item("privacy","security","Does Libérons sell my protected content?","Libérons vend-il mes contenus protégés ?","No. Libérons processes content as needed to provide the protection, storage and recovery features you request and does not sell protected content for targeted advertising.","Non. Libérons traite les contenus dans la mesure nécessaire pour fournir les fonctions de protection, de stockage et de récupération que vous demandez et ne vend pas les contenus protégés à des fins de publicité ciblée.","confidentialité vendre publicité données"),
        item("permissions","security","Why does Libérons need Photos access?","Pourquoi Libérons a-t-il besoin d’accéder à Photos ?","Photos access is required for the photo and video actions you request, including selecting originals for protection, restoring media and removing confirmed protected local copies. You can review this permission in iPhone Settings.","L’accès à Photos est nécessaire pour les actions sur les photos et vidéos que vous demandez, notamment sélectionner les originaux à protéger, restaurer des médias et retirer des copies locales dont la protection est confirmée. Vous pouvez contrôler cette autorisation dans les réglages de l’iPhone.","autorisation photos accès réglages"),
        item("files-access","security","Why does Libérons ask me to choose a folder in Files?","Pourquoi Libérons me demande-t-il de choisir un dossier dans Fichiers ?","The folder picker lets you explicitly choose the location Libérons may analyze. Access is used for the operation you request, such as analyzing, protecting or deleting selected files.","Le sélecteur de dossier vous permet de choisir explicitement l’emplacement que Libérons peut analyser. Cet accès est utilisé pour l’opération que vous demandez, par exemple analyser, protéger ou supprimer des fichiers sélectionnés.","autorisation fichiers dossier accès"),

        item("failed","troubleshooting","Why did protection fail?","Pourquoi une protection a-t-elle échoué ?","Common causes include a lost connection, an original temporarily unavailable, insufficient Libérons capacity or a temporary service interruption. An item is not presented as protected unless its protected copy has been confirmed.","Les causes fréquentes sont une perte de connexion, un original temporairement indisponible, un espace Libérons insuffisant ou une interruption temporaire du service. Un élément n’est pas présenté comme protégé tant que sa copie protégée n’a pas été confirmée.","échec erreur réseau capacité réessayer"),
        item("limited-photos","troubleshooting","Why can Libérons not see all my photos?","Pourquoi Libérons ne voit-il pas toutes mes photos ?","Check the Photos permission for Libérons. If iOS is set to Limited Access, Libérons can work only with the photos you allowed. You can change this choice in iPhone Settings.","Vérifiez l’autorisation Photos de Libérons. Si iOS est réglé sur Accès limité, Libérons ne peut travailler qu’avec les photos que vous avez autorisées. Vous pouvez modifier ce choix dans les réglages de l’iPhone.","photos manquantes accès limité autorisation"),
        item("slow","troubleshooting","Why is protection slow?","Pourquoi la protection est-elle lente ?","Speed depends on your connection, content size, whether an original must first be retrieved from iCloud and iOS power or thermal conditions. Large videos naturally take longer. Libérons prioritizes confirmed protection over declaring an item protected too early.","La vitesse dépend de votre connexion, de la taille du contenu, de la récupération éventuelle de l’original depuis iCloud et des conditions d’alimentation ou de température d’iOS. Les vidéos volumineuses prennent naturellement plus de temps. Libérons privilégie une protection confirmée plutôt que de déclarer un élément protégé trop tôt.","lent vitesse vidéo icloud température batterie"),
        item("offline","troubleshooting","What happens if my connection drops during protection?","Que se passe-t-il si ma connexion coupe pendant la protection ?","The affected transfer can fail or pause and be retried. Libérons does not mark the item protected unless the protected copy is confirmed.","Le transfert concerné peut échouer ou se mettre en pause puis être réessayé. Libérons ne marque pas l’élément comme protégé tant que la copie protégée n’est pas confirmée.","hors ligne internet coupure connexion réessayer"),
        item("support","troubleshooting","What should I send to support if I have a problem?","Que dois-je envoyer au support en cas de problème ?","Describe what you were doing, what you expected, what happened and any error displayed. A screenshot can help. Never send your password, verification codes or full payment-card number.","Décrivez ce que vous faisiez, ce que vous attendiez, ce qui s’est produit et le message d’erreur affiché. Une capture d’écran peut aider. N’envoyez jamais votre mot de passe, vos codes de vérification ni votre numéro complet de carte de paiement.","support aide problème capture erreur mot de passe carte")
    ] }

    private var filteredItems:[FAQItem] { let query=normalize(searchText); return items.filter { entry in guard selectedCategory=="all" || entry.category==selectedCategory else{return false}; guard !query.isEmpty else{return true}; let searchable=normalize([entry.questionEN,entry.questionFR,entry.answerEN,entry.answerFR,entry.keywords,categoryTitle(entry.category)].joined(separator:" ")); let tokens=query.split(separator:" ").map(String.init).filter{$0.count>1}; return searchable.contains(query) || (!tokens.isEmpty && tokens.allSatisfy{searchable.contains($0)}) } }

    var body:some View {
        List {
            Section { VStack(alignment:.leading,spacing:8) { Label(language.text("Libérons Support","Assistance Libérons"),systemImage:"message.badge.fill").font(.headline).foregroundStyle(.blue); Text(language.text("Find clear guidance for protection, files, storage, recovery, your account and billing.","Retrouvez des réponses claires sur la protection, les fichiers, l’espace, la récupération, votre compte et la facturation.")).font(.subheadline).foregroundStyle(.secondary) }.padding(.vertical,4) }
            Section { ScrollView(.horizontal,showsIndicators:false) { HStack(spacing:8) { ForEach(categories,id:\.0) { category in Button { selectedCategory=category.0 } label:{ Text(language.text(category.1,category.2)).font(.subheadline.weight(.semibold)).padding(.horizontal,13).padding(.vertical,8).background(selectedCategory==category.0 ? Color.blue:Color.secondary.opacity(0.12),in:Capsule()).foregroundStyle(selectedCategory==category.0 ? Color.white:Color.primary) }.buttonStyle(.plain) } }.padding(.vertical,2) } }
            if filteredItems.isEmpty { Section { ContentUnavailableView(language.text("No answer found","Aucune réponse trouvée"),systemImage:"magnifyingglass",description:Text(language.text("Try another word, choose All, or contact Libérons Support.","Essayez un autre mot, choisissez Tout ou contactez l’assistance Libérons."))) } }
            else { ForEach(categories.filter{category in category.0 != "all" && filteredItems.contains(where:{$0.category==category.0})},id:\.0) { category in Section(language.text(category.1,category.2)) { ForEach(filteredItems.filter{$0.category==category.0}) { entry in faq(language.text(entry.questionEN,entry.questionFR),language.text(entry.answerEN,entry.answerFR)) } } } }
            Section(language.text("Still need help?","Encore besoin d’aide ?")) { LiberonsExternalRow(icon:"envelope.fill",title:"support@liberons.com",subtitle:language.text("Email Libérons Support","Écrire à l’assistance Libérons")){emailSupport()} }
        }
        .searchable(text:$searchText,placement:.navigationBarDrawer(displayMode:.always),prompt:language.text("Search protection, files, storage…","Rechercher protection, fichiers, espace…"))
        .navigationTitle(language.text("Help & support","Aide et support")).navigationBarTitleDisplayMode(.inline)
    }

    private func item(_ id:String,_ category:String,_ enQ:String,_ frQ:String,_ enA:String,_ frA:String,_ keywords:String)->FAQItem{FAQItem(id:id,category:category,questionEN:enQ,questionFR:frQ,answerEN:enA,answerFR:frA,keywords:keywords)}
    @ViewBuilder private func faq(_ question:String,_ answer:String)->some View{DisclosureGroup(question){Text(answer).font(.subheadline).foregroundStyle(.secondary).padding(.vertical,6).textSelection(.enabled)}}
    private func normalize(_ value:String)->String{value.folding(options:[.diacriticInsensitive,.caseInsensitive],locale:.current).lowercased().replacingOccurrences(of:"’",with:"'")}
    private func categoryTitle(_ id:String)->String{categories.first(where:{$0.0==id}).map{"\($0.1) \($0.2)"} ?? id}
    private func emailSupport(){guard let url=URL(string:"mailto:support@liberons.com?subject=Lib%C3%A9rons%20Support") else{return};UIApplication.shared.open(url)}
}

struct LiberonsAboutView: View {
    @ObservedObject var language: LanguageStore
    var body: some View {
        ScrollView {
            VStack(spacing: 20) {
                ZStack { RoundedRectangle(cornerRadius: 28).fill(Color.blue.gradient).frame(width: 92, height: 92); Image(systemName: "icloud.and.arrow.up.fill").font(.system(size: 40, weight: .semibold)).foregroundStyle(.white) }
                VStack(spacing: 6) { Text("Libérons").font(.system(size: 34, weight: .bold, design: .rounded)); Text(language.text("Keep your memories. Free your space.", "Gardez vos souvenirs. Libérez votre espace.")).font(.headline).foregroundStyle(.secondary).multilineTextAlignment(.center) }
                aboutCard {
                    Text(language.text("Your content, protected. Your space, reclaimed.", "Vos contenus protégés. Votre espace retrouvé.")).font(.title3.bold())
                    Text(language.text("Libérons protects photos, videos and files so you can reclaim space on your iPhone while keeping important content available in your Libérons Library.", "Libérons protège vos photos, vidéos et fichiers afin de vous permettre de récupérer de l’espace sur votre iPhone tout en gardant vos contenus importants disponibles dans votre Bibliothèque Libérons."))
                    Divider()
                    aboutPoint("checkmark.icloud.fill", language.text("Protection you can verify", "Une protection vérifiable"), language.text("An item is considered protected only after its protected copy has been confirmed.", "Un élément n’est considéré comme protégé qu’après confirmation de sa copie protégée."))
                    aboutPoint("iphone", language.text("You remain in control", "Vous gardez le contrôle"), language.text("Protection and removing an original are separate actions.", "La protection et le retrait d’un original restent deux actions distinctes."))
                    aboutPoint("arrow.down.to.line.compact", language.text("Access when you need it", "Vos contenus, quand vous en avez besoin"), language.text("Protected content remains available in your Libérons Library, subject to your account access.", "Vos contenus protégés restent accessibles dans votre Bibliothèque Libérons, selon l’état de votre compte."))
                }
                aboutCard { Text(language.text("Libérons online", "Libérons en ligne")).font(.headline); LiberonsExternalRow(icon: "globe", title: language.text("Visit Libérons", "Découvrir Libérons"), subtitle: language.text("Official website", "Site officiel")) { open(.home) } }
                aboutCard { HStack { Text(language.text("App version", "Version de l’app")); Spacer(); Text(version).foregroundStyle(.secondary) }; Divider(); HStack { Text(language.text("Service operator", "Exploitant du service")); Spacer(); Text("Freddy Mboma").foregroundStyle(.secondary) }; Divider(); HStack { Text(language.text("Based in", "Établi au")); Spacer(); Text("Canada").foregroundStyle(.secondary) } }
                Text(language.text("Libérons · Built to protect what matters and give your space back.", "Libérons · Protéger ce qui compte. Retrouver votre espace.")).font(.caption).foregroundStyle(.secondary).multilineTextAlignment(.center)
                Text("© 2026 Libérons").font(.caption).foregroundStyle(.secondary).padding(.bottom, 12)
            }.padding(24)
        }.background(LiberonsTheme.canvas).navigationTitle(language.text("About Libérons", "À propos de Libérons")).navigationBarTitleDisplayMode(.inline)
    }
    @ViewBuilder private func aboutCard<Content: View>(@ViewBuilder content: () -> Content) -> some View { VStack(alignment: .leading, spacing: 14) { content() }.frame(maxWidth: .infinity, alignment: .leading).padding(20).background(LiberonsTheme.card, in: RoundedRectangle(cornerRadius: 24, style: .continuous)) }
    @ViewBuilder private func aboutPoint(_ icon: String, _ title: String, _ detail: String) -> some View { HStack(alignment: .top, spacing: 12) { Image(systemName: icon).foregroundStyle(.blue).frame(width: 24).padding(.top, 2); VStack(alignment: .leading, spacing: 3) { Text(title).font(.subheadline.bold()); Text(detail).font(.subheadline).foregroundStyle(.secondary) } } }
    private func open(_ destination: LiberonsWebDestination) { guard let url = destination.url(for: language.language) else { return }; UIApplication.shared.open(url) }
    private var version: String { let version = Bundle.main.infoDictionary?["CFBundleShortVersionString"] as? String ?? "—"; let build = Bundle.main.infoDictionary?["CFBundleVersion"] as? String ?? "—"; return "\(version) (\(build))" }
}
